// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 blockNum, uint256 timestamp) public {
        amount = bound(amount, 10 ether, 10 ether);
        vm.assume(timestamp > 0);
        vm.warp(timestamp);
        vm.roll(blockNum);
        uint256 preBal = address(c).balance;
        address caller = address(0x1234);
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "call must succeed");
        uint256 postBal = address(c).balance;
        if (blockNum % 15 == 0) {
            assertTrue(postBal == 0);
        } else {
            assertTrue(postBal == preBal + amount);
        }
    }
}
